```powershell
param(
    [Parameter(Mandatory = $true)]
    [string]$RootPath,
    [Parameter(Mandatory = $true)]
    [string]$ZipPath
)

$ErrorActionPreference = 'Stop'

if (-not (Test-Path -LiteralPath $RootPath -PathType Container)) {
    throw "RootPath '$RootPath' does not exist or is not a directory."
}

$files = Get-ChildItem -Path $RootPath -Recurse -File -Filter '*.log' |
    Where-Object { $_.Length -gt 10MB }

if ($files.Count -eq 0) {
    Write-Host "No .log files larger than 10MB found under '$RootPath'."
    exit 0
}

if (Test-Path -LiteralPath $ZipPath) {
    Remove-Item -LiteralPath $ZipPath -Force
}

Add-Type -AssemblyName System.IO.Compression.FileSystem

$zipFullPath = [System.IO.Path]::GetFullPath($ZipPath)
$zipDir      = [System.IO.Path]::GetDirectoryName($zipFullPath)

if (-not (Test-Path -LiteralPath $zipDir)) {
    New-Item -ItemType Directory -Path $zipDir | Out-Null
}

$zip = [System.IO.Compression.ZipFile]::Open($zipFullPath, 'Create')

try {
    foreach ($file in $files) {
        $relativePath = Resolve-Path -LiteralPath $file.FullName |
                        ForEach-Object { $_.Path.Substring($RootPath.Length).TrimStart('\','/') }
        [System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile(
            $zip,
            $file.FullName,
            $relativePath,
            [System.IO.Compression.CompressionLevel]::Optimal
        ) | Out-Null
    }
}
finally {
    $zip.Dispose()
}
